'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var EPS = require( '@stdlib/constants/float64/eps' );


// VARIABLES //

var quantile = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( quantile instanceof Error )
};


// FIXTURES //

var data = require( './fixtures/julia/data.json' );
var p = data.p;
var sigma = data.sigma;
var expected = data.expected;


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'if any argument is NaN, the function returns NaN', opts, function test( t ) {
	t.ok( isnan( quantile( NaN, 1.0 ) ), 'p NaN' );
	t.ok( isnan( quantile( 0.5, NaN ) ), 'sigma NaN' );
	t.end();
});

tape( 'if p is outside [0,1], the function returns NaN', opts, function test( t ) {
	t.ok( isnan( quantile( -0.1, 1.0 ) ), 'p < 0' );
	t.ok( isnan( quantile( 1.1, 1.0 ) ), 'p > 1' );
	t.end();
});

tape( 'if sigma < 0, the function returns NaN', opts, function test( t ) {
	t.ok( isnan( quantile( 0.5, -1.0 ) ), 'negative sigma' );
	t.end();
});

tape( 'if sigma = 0, the quantile is 0 for all p', opts, function test( t ) {
	t.strictEqual( quantile( 0.0, 0.0 ), 0.0 );
	t.strictEqual( quantile( 0.5, 0.0 ), 0.0 );
	t.strictEqual( quantile( 1.0, 0.0 ), 0.0 );
	t.end();
});

tape( 'p = 1 returns +Infinity', opts, function test( t ) {
	t.strictEqual( quantile( 1.0, 1.0 ), PINF );
	t.end();
});

tape( 'the native function evaluates the half-normal quantile correctly', opts, function test( t ) {
	var delta;
	var tol;
	var y;
	var i;

	for ( i = 0; i < p.length; i++ ) {
		y = quantile( p[i], sigma[i] );
		if ( expected[i] !== null ) {
			if ( y === expected[i] ) {
				t.strictEqual( y, expected[i], 'exact match' );
			} else {
				delta = abs( y - expected[i] );
				tol = 40.0 * EPS * abs( expected[i] );
				t.ok(delta <= tol, 'p: '+p[i]+', sigma: '+sigma[i]+', y: '+y+', expected: '+expected[i]);
			}
		}
	}
	t.end();
});
